// For each (custodian, source) pair, prepare a per-source dispatch payload.
// The flow's per-source nodes receive these payloads.
const rows = $input.all().map(r => r.json);
const trigger = $('Collection Request').item.json;

if (rows.length === 0) {
  return [{ json: { status: 'halted', reason: 'no_approved_plan_rows', collection_plan_id: trigger.collection_plan_id } }];
}

const out = rows.map(row => ({
  json: {
    matter_id: trigger.matter_id,
    collection_plan_id: trigger.collection_plan_id,
    plan_sha: row.plan_sha,
    custodian_id: row.custodian_id,
    source: row.source,
    scope: typeof row.scope_json === 'string' ? JSON.parse(row.scope_json) : row.scope_json,
    requested_at: new Date().toISOString(),
    collection_id: `coll-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
  }
}));

return out;

// Compute SHA-256 of the export, append chain-of-custody record.
// Skeleton — production flow includes the actual export-fetch step.
const crypto = require('crypto');
const input = $input.first().json;
const dispatch = $('Per-Source Dispatch').item.json;

// In production: fetch the actual export bytes here, hash them.
// Skeleton uses a deterministic placeholder so the audit record shape is correct.
const placeholderHash = crypto.createHash('sha256').update(`${dispatch.collection_id}-${dispatch.source}`).digest('hex');

return [{
  json: {
    matter_id: dispatch.matter_id,
    collection_id: dispatch.collection_id,
    custodian_id: dispatch.custodian_id,
    source: dispatch.source,
    plan_sha: dispatch.plan_sha,
    collected_at: new Date().toISOString(),
    collected_by_service_account: $env.COLLECTION_SERVICE_ACCOUNT || 'ediscovery-bot@firm',
    hash: placeholderHash,
    file_count: input.fileCount || 0,
    byte_count: input.byteCount || 0,
    scope_summary: JSON.stringify(dispatch.scope).slice(0, 500),
    skeleton_warning: 'This skeleton flow does not fetch and hash actual export bytes. Production: replace with fetch + bytewise hash.',
  }
}];
